// dark matter, don't render near
// v+=vec3(dm,dm*.5,0.);
v+=fade;
v+=vec3(s,s*s,s*s*s*s)*a*brightness*fade;
// coloring based on distance
fade*=distfading;
// distance fading
fade*=fac;
s+=stepsize;
}
v=mix(vec3(length(v), length(v), length(v)),v,saturation);
// color adjust
fragColor = vec4(v*.03,1.);
uv *= 2.0 * ( cos(uTime * 2.0) -2.5);
// scale
float anim = sin(uTime * 12.0) * 0.1 + 1.0;
// anim between 0.9 - 1.1
fragColor*= vec4(happy_star(uv, anim) * vec3(0.5,0.5,0.55)*0.2, 1.0);
ret = fragColor;
}

void main() {
