uv.y = (uv.y * 4.0) - 2.0;
uv = vec2(-uv.x, uv.y);
uv *= uAspect.xy;
// CONV: Adjust this to flip the output (±uv.x, ±uv.y)
vec2 fragCoord  = uv;
// get coords and direction
// vec2 uv=fragCoord.xy/uTexSize.xy-.5;
//uv.y*=uTexSize.y/uTexSize.x;
uv*=0.4;
vec3 dir=vec3(uv*zoom,1.);
float time_scale = 0.5;
float time_conv = uTime * time_scale;
vec2 uv2 = fragCoord.xy / min(uTexSize.x, uTexSize.y);
uv2=normalize(vec3(uv,0.212)).xy;
float t = uTime * .1 + ((.25 + .05 * sin(uTime * .1))/(length(uv.xy) + .47)) * 12.2+uTime;
float si = sin(t);
float co = cos(t);
mat2 ma = mat2(co, si, -si, co);
;
vec2 fbm_scale = vec2(1.0, 1.0);
vec2 t_scale = vec2(5.0, 5.0);
vec2 x_offset = vec2(123.456, 0.0);
vec2 y_offset = vec2(349.234, 1704.2);
vec2 x_coords = (uv2 + x_offset) * fbm_scale;
float xo = fBm(vec3(x_coords, time_conv));
vec2 tx_coords = (uv2 + x_offset) * t_scale;
float xt = turbulence(vec3(tx_coords, time_conv));
vec2 y_coords = (uv2 + y_offset) * fbm_scale;
float yo = fBm(vec3(y_coords, time_conv));
vec2 ty_coords = (uv2 + y_offset) * t_scale;
float yt = turbulence(vec3(ty_coords, time_conv));
vec2 pixel = 1.0 / uTexSize.xy;
float max_po = 10.0;
vec2 po = max_po * vec2(xo + xt, yo + yt) * pixel;
po = multiply(po, transpose(mat2(cos(uTime)*2.,sin(uTime)*2.,-sin(uTime)*2.,cos(uTime)*2.)));
vec2 tc = fragCoord.xy / uTexSize.xy;
vec3 from=vec3(1.,.5,0.5);
dir.xy*=po;
// volumetric rendering
float s=0.1,fade=1.;
vec3 v=vec3(0., 0., 0.);
#ifdef bass_smooth
float fac = (int)vis_version > 2 ? 0.9*vis_intensity+vis_shift : (0.8 + 0.2*smoothstep( 0.0 , 2.0 ,(int)vis_version == 1 ? bass_smooth : audioLowSmooth))*vis_intensity+vis_shift;
#else
float fac = 0.9 + 0.02*smoothstep( 0.0 , 2.0 ,audioLowSmooth);
#endif
for (int r=0; r<volsteps; r++) {
vec3 p=from+s*dir*.5;
p = abs(vec3(tile,tile,tile)-mod_conv(p,vec3(tile*2.,tile*2.,tile*2.)));
// tiling fold
float pa,a=pa=0.;
for (int i=0; i<iterations; i++) {
p=abs(p)/dot(p,p)-formuparam;
// the magic formula
a+=abs(length(p)-pa);
// absolute sum of average change
pa=length(p);
  fragColor = vec4(ret, 1.0);
}

